// Lấy dữ liệu thô từ Search Messages
const inputData = $input.first().json;

// 1. Tách dữ liệu an toàn
const messages = inputData.items || [];      // Danh sách tin nhắn
const chatMetadata = inputData.chats || {};  // Danh sách thông tin nhóm

const results = [];

// 2. Duyệt qua từng tin nhắn
for (const msg of messages) {

  // --- BỘ LỌC CƠ BẢN (ĐÃ BẬT CHO PRODUCTION) ---

  // A. Bỏ qua tin nhắn do chính mình gửi (Sam gửi)
  // Logic: Chỉ khi Khách nhắn tin mới thì mới kích hoạt Workflow
  if (msg.isSender === true) continue;

  // B. Bỏ qua tin nhắn đã đọc (Chỉ xử lý tin mới chưa đọc)
  // Giúp tránh việc hệ thống quét lại tin cũ mỗi lần chạy
  if (msg.isUnread === false) continue; 

  const senderName = msg.senderName || "";
  const chatInfo = chatMetadata[msg.chatID] || {};
  const groupTitle = chatInfo.title || chatInfo.name || "";

  // --- DANH SÁCH CHẶN (INTERNAL GROUPS) - QUAN TRỌNG ---
  // Nếu tên nhóm là "The REAL Danta" hoặc chứa từ khóa nội bộ -> BỎ QUA NGAY
  // Giúp tránh việc bot bắt nhầm tin nhắn của thành viên nội bộ có chữ (B) trong tên
  if (groupTitle.includes("The REAL Danta") || groupTitle.includes("Danta Internal")) {
      continue;
  }

  // --- BỘ LỌC CLIENT VIP (BẮT BUỘC CÓ "(B)") ---

  // Kiểm tra: Tên người gửi HOẶC Tên nhóm phải chứa "(B)"
  // Ví dụ: "Client (B) - Jay" hoặc nhóm "Project (B)"
  const isClientPerson = senderName.includes("(B)");
  const isClientGroup = groupTitle.includes("(B)");

  // 3. QUYẾT ĐỊNH: CHỈ CHO QUA KHÁCH HÀNG ĐÍCH THỰC
  if (isClientPerson || isClientGroup) {

    // Ưu tiên lấy Tên Nhóm nếu là Group Client, hoặc Tên Người nếu là Khách lẻ
    msg.finalTitle = groupTitle || senderName || "Unknown Client (B)"; 

    // Đảm bảo chatID luôn đầy đủ
    msg.chatID = msg.chatID || chatInfo.id;

    // Đánh dấu loại khách hàng
    msg.clientType = "VIP Client (B)";

    results.push({
      json: msg
    });
  }
}

return results;

// 1. Lấy dữ liệu từ node ngay trước đó (HTTP Request)
const inputData = $input.first().json;

// --- ĐỒNG BỘ DỮ LIỆU TỪ GATHER MESSAGES ---
let originalContext = {};
try {
    // Gọi ngược lại node Gather Messages để lấy metadata chuẩn
    originalContext = $('Gather Messages').first().json;
} catch (e) {
    console.log("⚠️ Cannot find data from Gather Messages");
}

// Ưu tiên lấy chatID từ Gather Messages vì nó đã được xử lý kỹ
const finalChatID = originalContext.chatID || inputData.chatID || inputData.id;

// Ưu tiên lấy Tên Khách Hàng chuẩn (finalTitle) từ Gather Messages
const bestCustomerName = originalContext.finalTitle || inputData.title || inputData.senderName || "Customer";

// 2. Lấy danh sách tin nhắn
const messages = inputData.messages || inputData.items || [];

// 3. Xử lý nội dung hội thoại
const sortedMessages = messages.slice().reverse();

let conversationTranscript = "";

for (const msg of sortedMessages) {
  if (!msg.text) continue;

  let senderRole = "";

  if (msg.isSender) {
      senderRole = "👨‍💻 Support Team (Sam)";
  } else {
      senderRole = `👤 ${msg.senderName || "Customer"}`;
  }

  conversationTranscript += `${senderRole}: ${msg.text}\n`;
}

// --- LOGIC MỚI: TẠO LABEL CHUẨN JIRA ---
// Yêu cầu: Jira Label không chấp nhận khoảng trắng hay ký tự đặc biệt.

// Lấy tên khách hàng làm gốc (Ví dụ: "(B) [Jay] Phuc Nguyen")
const rawName = (bestCustomerName || "Client").toString();

// Hàm replace này sẽ xóa tất cả ký tự KHÔNG PHẢI là chữ (a-z, A-Z) hoặc số (0-9)
// Kết quả: "BJayPhucNguyen"
let cleanLabel = rawName.replace(/[^a-zA-Z0-9]/g, "");

// Fallback: Nếu tên khách toàn ký tự đặc biệt (VD: "!!!") bị xóa hết thành rỗng
// Thì lấy ID tin nhắn làm label để đảm bảo không bị lỗi
if (!cleanLabel || cleanLabel.length < 3) {
    // Lấy 10 ký tự đầu của ChatID làm label dự phòng
    const safeID = (finalChatID || "").toString().replace(/[^a-zA-Z0-9]/g, "");
    cleanLabel = "Client" + safeID.substring(0, 10);
}

return {
  json: {
    conversation_history: conversationTranscript,
    chatID: finalChatID,

    // Tên hiển thị đầy đủ (để humans đọc)
    customerName: bestCustomerName,

    // LABEL CHUẨN JIRA (Để máy đọc/tìm kiếm)
    // Node "Get Open Task" sẽ dùng biến này để tìm vé cũ
    jiraLabel: cleanLabel,

    // Giữ lại các dữ liệu khác nếu cần
    ...inputData 

  }
};

// Lấy văn bản từ AI
const inputItem = $input.first();
const aiOutputText = inputItem ? (inputItem.json.text || "{}") : "{}";
const results = [];

let ticketData = {};

// --- BƯỚC 1: PARSE JSON AN TOÀN ---
try {
    // Làm sạch Markdown và khoảng trắng
    const cleanJson = aiOutputText.replace(/```json/g, "").replace(/```/g, "").trim();
    ticketData = JSON.parse(cleanJson);
} catch (e) {
    console.log("⚠️ JSON Parse lỗi nhẹ, thử dùng Regex cứu dữ liệu...");
    // Backup: Nếu JSON lỗi, dùng Regex để "gắp" trường decision
    const decisionMatch = aiOutputText.match(/"decision":\s*"([^"]+)"/i);
    if (decisionMatch) ticketData.decision = decisionMatch[1];
}

// --- BƯỚC 2: PHIÊN DỊCH LOGIC (QUAN TRỌNG NHẤT) ---
// Chuyển đổi "decision" của AI thành "is_actionable" cho Workflow hiểu
if (ticketData.decision) {
    const d = ticketData.decision.toUpperCase();

    // Những quyết định này được coi là "Cần hành động" (Actionable)
    if (d === 'CREATE_SUBTASK' || d === 'CREATE_PARENT' || d === 'COMMENT' || d === 'TASK') {
        ticketData.is_actionable = true;
    } else {
        // IGNORE hoặc khác -> Không làm gì
        ticketData.is_actionable = false;
    }
} else {
    // Fallback: Nếu không tìm thấy decision, mặc định là false
    if (ticketData.is_actionable === undefined) {
        ticketData.is_actionable = false;
    }
}

// --- BƯỚC 3: ĐỒNG BỘ DỮ LIỆU GỐC (ĐÃ SỬA LỖI TÊN KHÁCH) ---
try {
    // 1. Lấy dữ liệu từ Format Chat (để lấy conversation_history)
    const formatChatNode = $('Format Chat').first();
    const originalData = formatChatNode ? formatChatNode.json : {};

    // 2. 🔥 QUAN TRỌNG: Lấy dữ liệu từ Gather Messages (để lấy Tên Khách VIP)
    // Vì Format Chat có thể đã làm mất trường finalTitle
    const gatherNode = $('Gather Messages').first();
    const gatherData = gatherNode ? gatherNode.json : {};

    // Logic chọn tên thông minh nhất:
    // Ưu tiên lấy finalTitle từ Gather Messages -> Nếu không có thì lấy senderName -> Cuối cùng mới là Customer
    const bestCustomerName = gatherData.finalTitle || originalData.finalTitle || originalData.senderName || "Customer";

    // Merge thông tin vào ticketData
    ticketData.customerName = bestCustomerName;
    ticketData.conversation_history = originalData.conversation_history; // Giữ lại lịch sử chat

    // Đảm bảo ID không bị mất
    ticketData.chatID = originalData.chatID || gatherData.chatID;
    ticketData.message_id = originalData.id || gatherData.id;

} catch (e) {
    console.log("⚠️ Không lấy được dữ liệu gốc chat: " + e.message);
    ticketData.customerName = "Customer (Fallback)";
}

// --- BƯỚC 4: OUTPUT ---
// Chỉ đẩy ra nếu là Actionable (True)
if (ticketData.is_actionable === true) {

    // Tự động đẩy Priority lên High nếu là Bug
    if ((ticketData.summary && ticketData.summary.toLowerCase().includes("bug")) || 
        ticketData.category === "Bug") {
        ticketData.priority = "High";
    }

    results.push({ json: ticketData });
} else {
    console.log("🛑 AI quyết định IGNORE (Bỏ qua) tin nhắn này.");
}

return results;

// 1. TẠO DANH SÁCH ĐEN (BLACKLIST)
// Lấy tất cả message_id tìm thấy trong Sheet và chuyển thành Chuỗi (String)
const foundIds = $input.all()
    .map(item => item.json.message_id) // Lấy cột message_id
    .filter(id => id) // Lọc bỏ các dòng rỗng (nếu có)
    .map(id => id.toString().trim()); // QUAN TRỌNG: Chuyển thành chuỗi và xóa khoảng trắng thừa

// 2. LẤY DANH SÁCH TIN NHẮN GỐC
const allOriginalMsgs = $('Gather Messages').all();

const newMessages = [];

// 3. DUYỆT VÀ SO SÁNH
for (const msgItem of allOriginalMsgs) {
    const msg = msgItem.json;

    // Chuyển ID tin nhắn gốc thành chuỗi để so sánh tương xứng
    // (Dùng msg.id hoặc msg.chatID tùy vào cột bạn lưu trong sheet là gì)
    // Ở đây tôi dùng msg.id theo ảnh của bạn
    const msgIdToCheck = (msg.id || "").toString().trim();

    // 4. KIỂM TRA
    if (foundIds.includes(msgIdToCheck)) {
        // Nếu tìm thấy trong danh sách đen -> TRÙNG -> BỎ QUA
        // (Không làm gì cả)
    } else {
        // Nếu không tìm thấy -> TIN MỚI -> LẤY
        newMessages.push({
            json: msg
        });
    }
}

// 5. Trả về danh sách tin mới hoàn toàn
return newMessages;

