// --- CẤU HÌNH: Mode "Run Once for All Items" ---

const aiInput = $input.first();
const aiData = aiInput ? aiInput.json : {};

// Lấy dữ liệu vệ tinh
const gatherNode = $('Gather Messages').first(); 
const gatherData = gatherNode ? gatherNode.json : {};
const chatNode = $('Format Chat').first();
const chatData = chatNode ? chatNode.json : {};

// 2. Lấy danh sách Jira
let jiraData = [];
try {
    jiraData = $('Get Open Task').all();
} catch (e) { }

// LOGIC TÌM MASTER TICKET (CHUẨN 100%)
// Master Ticket là vé KHÔNG CÓ trường 'parent'.
// Subtask luôn có trường 'parent' trỏ về Master.
let masterTicketJson = null;

if (jiraData.length > 0) {
    const foundMaster = jiraData.find(item => {
        const fields = item.json.fields;
        // Logic: Có fields VÀ (Không có parent HOẶC parent bằng null)
        return fields && (!fields.parent);
    });

    if (foundMaster) {
        masterTicketJson = foundMaster.json;
    }
}

const hasMaster = !!masterTicketJson;

// 3. Xác định hướng đi
let destination = '';
let operation = '';
const aiDecision = (aiData.decision || '').toUpperCase();

if (hasMaster) {
    // === ĐÃ CÓ VÉ MASTER ===
    // Nếu AI bảo tạo Subtask -> OK, làm luôn.
    if (aiDecision === 'CREATE_SUBTASK' || aiDecision === 'TASK' || aiDecision === 'CREATE_PARENT') {
        destination = 'SUBTASK';
        operation = 'CREATE_SUBTASK';
    } else {
        destination = 'COMMENT';
        operation = 'ADD_COMMENT';
    }
} else {
    // === CHƯA CÓ VÉ MASTER ===
    // Bắt buộc phải tạo Master trước
    destination = 'PARENT_ONLY';
    operation = 'CREATE_PARENT';
}

// 4. Chuẩn bị Output
const outputJson = {
    ...aiData,
    ...gatherData, 
    ...chatData, 

    final_message_id: gatherData.id || "unknown_id",
    final_content: gatherData.text || "",
    customerName: chatData.customerName || gatherData.finalTitle, 

    // Key này luôn luôn đúng là Master Ticket
    parentKey: hasMaster ? masterTicketJson.key : undefined,
    parentId: hasMaster ? masterTicketJson.id : undefined,

    route_destination: destination,
    operation: operation
};

return [{ json: outputJson }];

// Lấy dữ liệu từ Router
const items = $input.all();

// SỬA LỖI: Lọc theo quyết định của Router (route_destination) 
// thay vì quyết định của AI (decision)
const parentItems = items.filter(item => item.json.route_destination === 'PARENT_ONLY');

return parentItems;

