try {
    // Kỹ thuật "Nhảy cóc": Lấy lại dữ liệu meeting_time từ node AI Json Parse
    // $('AI Json Parse') giúp truy cập dữ liệu gốc dù đã qua node Jira
    const aiData = $('AI Json Parse').first().json;
    meetingTime = aiData.meeting_time;
} catch (e) {
    console.log("⚠️ Không tìm thấy dữ liệu meeting_time.");
}

// LOGIC CÔNG TẮC ĐÓNG/NGẮT:
// 1. Kiểm tra xem có giờ họp không? (Khác null, khác rỗng, khác chuỗi "null")
if (meetingTime && meetingTime !== null && meetingTime !== "null") {
    // ✅ CÓ GIỜ -> Trả về data để kích hoạt node Calendar chạy
    return jiraItems; 
} else {
    // ⛔ KHÔNG CÓ GIỜ -> Trả về mảng rỗng -> Node Calendar sẽ KHÔNG CHẠY
    return []; 
}

